/// <summary>
/// CB521_ExciseRegister
/// Service class for excise information update table
/// </summary>
class METExciseInformationTableUpdateService extends SysOperationServiceBase
{
    METDutyRollVariance             dutyRollVariance;
    METExciseInformationTable       metExciseInformationTable;
    RecordInsertList                recordInsertList = new RecordInsertList(tableNum(METExciseInformationTable), false, false, false, false, false);
    RecordInsertList                dutyRollVarianceRecordInsertList = new RecordInsertList(tableNum(METDutyRollVariance));

}

Method.Source:
    /// <summary>
    /// Process method to initiate service class
    /// </summary>
    /// <param name = "_contract">Contract class</param>
    public void process(METExciseInformationTableUpdateContract     _contract)
    {
        BatchHeader                                 batchHeader;
        SysOperationServiceController               runTaskController;
        METExciseRegisterOriginTypes                metExciseRegisterOriginTypes;
        METExciseInformationTableUpdateContract     contract;

        while select ReferenceId, TransactionType from metExciseRegisterOriginTypes
            where metExciseRegisterOriginTypes.UpdateRegister == NoYes::Yes
        {
            if (this.isExecutingInBatch())
            {
                ttsbegin;

                runTaskController = new SysOperationServiceController(classStr(METExciseInformationTableUpdateService), methodStr(METExciseInformationTableUpdateService, runExciseInformationTableUpdate));
            
                contract = runTaskController.getDataContractObject('_contract');

                if (!batchHeader)
                {
                    batchHeader = this.getCurrentBatchHeader();
                }

                contract.parmReferenceId(metExciseRegisterOriginTypes.ReferenceId);
                contract.parmTransactionType(metExciseRegisterOriginTypes.TransactionType);

                batchHeader.addRuntimeTask(runTaskController, this.getCurrentBatchTask().RecId);

                ttscommit;
            }
            else
            {
                ttsbegin;

                contract = new METExciseInformationTableUpdateContract();

                contract.parmReferenceId(metExciseRegisterOriginTypes.ReferenceId);
                contract.parmTransactionType(metExciseRegisterOriginTypes.TransactionType);

                this.runExciseInformationTableUpdate(contract);

                ttscommit;
            }
        }

        if (batchHeader)
        {
            batchHeader.save();
        }
    }

    /// <summary>
    /// Run process method
    /// </summary>
    /// <param name = "_contract">Contract class reference</param>
    public void runExciseInformationTableUpdate(METExciseInformationTableUpdateContract     _contract)
    {
        METInventTransExciseRegisterUpdateView          metInventTransExciseRegisterUpdateView;
        boolean                                         validInsert;

        while select metInventTransExciseRegisterUpdateView
            where metInventTransExciseRegisterUpdateView.ReferenceCategory == _contract.parmReferenceId()
                notexists join metExciseInformationTable
                    where metInventTransExciseRegisterUpdateView.InventTransRecId == metExciseInformationTable.InventTransRefRecId
        {
            validInsert = false;

            if ((_contract.parmTransactionType() == METTransactionType::Positive && metInventTransExciseRegisterUpdateView.Qty > 0) ||
                (_contract.parmTransactionType() == METTransactionType::Negative && metInventTransExciseRegisterUpdateView.Qty < 0))
            {
                metExciseInformationTable.clear();
                metExciseInformationTable.ReferenceNumber       = metInventTransExciseRegisterUpdateView.ReferenceId;
                metExciseInformationTable.InventTransType       = metInventTransExciseRegisterUpdateView.ReferenceCategory;
                metExciseInformationTable.InventTransRefRecId   = metInventTransExciseRegisterUpdateView.InventTransRecId;
                metExciseInformationTable.ItemId                = metInventTransExciseRegisterUpdateView.ItemId;
                metExciseInformationTable.SiteId                = InventDim::find(metInventTransExciseRegisterUpdateView.inventDimId).inventSiteId;
                metExciseInformationTable.InventTransId         = metInventTransExciseRegisterUpdateView.InventTransId;

                if (metInventTransExciseRegisterUpdateView.ReferenceCategory == InventTransType::Purch)
                {
                    PurchStatus purchStatus = PurchTable::find(metInventTransExciseRegisterUpdateView.ReferenceId).PurchStatus;
 
                    if (purchStatus == PurchStatus::Invoiced ||  purchStatus == PurchStatus::Received)
                    {
                        metExciseInformationTable.InventoryQty  = metInventTransExciseRegisterUpdateView.Qty;
                        metExciseInformationTable.AvailableQty  = metExciseInformationTable.InventoryQty;
                        metExciseInformationTable.TransactionQty = PurchLine::findInventTransId(metInventTransExciseRegisterUpdateView.InventTransId).PurchQty;

                        METExciseRegisterEntry metExciseRegisterEntry;

                        select firstonly Lodgement, RecId, DutyRateReceived, OriginDocumentNumber from metExciseRegisterEntry
                            where metExciseRegisterEntry.ItemId == metInventTransExciseRegisterUpdateView.ItemId &&
                                metExciseRegisterEntry.OrderNumber == metInventTransExciseRegisterUpdateView.ReferenceId &&
                                metExciseRegisterEntry.Migrated == NoYes::No;

                        if (metExciseRegisterEntry.RecId)
                        {
                            this.initialiseAdditionalDetailsForExciseInformation(metExciseInformationTable,
                                metExciseRegisterEntry,
                                metInventTransExciseRegisterUpdateView,
                                metInventTransExciseRegisterUpdateView.ReferenceCategory);

                            validInsert = true;
                        }
                    }
                }
                else if (metInventTransExciseRegisterUpdateView.ReferenceCategory == InventTransType::Sales)
                {
                    if (SalesTable::find(metInventTransExciseRegisterUpdateView.ReferenceId).SalesStatus == SalesStatus::Invoiced)
                    {
                        metExciseInformationTable.InventoryQty  = metInventTransExciseRegisterUpdateView.Qty;
                        metExciseInformationTable.AvailableQty  = 0.00;

                        validInsert = true;
                    }
                }
                else if (metInventTransExciseRegisterUpdateView.ReferenceCategory == InventTransType::TransferOrderShip)
                {
                    metExciseInformationTable.InventoryQty  = metInventTransExciseRegisterUpdateView.Qty;
                    metExciseInformationTable.AvailableQty  = metExciseInformationTable.InventoryQty;
                    
                    METExciseRegisterEntry metExciseRegisterEntry;
                    select firstonly reverse Lodgement, RecId, DutyRateReceived, OriginDocumentNumber from metExciseRegisterEntry
                        where metExciseRegisterEntry.ItemId == metInventTransExciseRegisterUpdateView.ItemId &&
                            metExciseRegisterEntry.OrderNumber == metInventTransExciseRegisterUpdateView.ReferenceId &&
                            metExciseRegisterEntry.Migrated == NoYes::No;

                    if (metExciseRegisterEntry.RecId)
                    {
                        this.initialiseAdditionalDetailsForExciseInformation(metExciseInformationTable,
                            metExciseRegisterEntry,
                            metInventTransExciseRegisterUpdateView,
                            metInventTransExciseRegisterUpdateView.ReferenceCategory);

                        validInsert = true;
                    }
                }
                else if (metInventTransExciseRegisterUpdateView.ReferenceCategory == InventTransType::TransferOrderReceive)
                {
                    if (InventTransferTable::find(metExciseInformationTable.ReferenceNumber).TransferStatus == InventTransferStatus::Received)
                    {
                        metExciseInformationTable.InventoryQty  = metInventTransExciseRegisterUpdateView.Qty;
                        metExciseInformationTable.AvailableQty  = metExciseInformationTable.InventoryQty;
                        metExciseInformationTable.TransactionQty = InventTransferLine::findTransIdReceive(metInventTransExciseRegisterUpdateView.InventTransId).QtyReceived;

                        METExciseRegisterEntry metExciseRegisterEntry;
                        select firstonly reverse Lodgement, RecId, DutyRateReceived, OriginDocumentNumber from metExciseRegisterEntry
                        where metExciseRegisterEntry.ItemId == metInventTransExciseRegisterUpdateView.ItemId &&
                            metExciseRegisterEntry.OrderNumber == metInventTransExciseRegisterUpdateView.ReferenceId &&
                            metExciseRegisterEntry.Migrated == NoYes::No;

                        if (metExciseRegisterEntry.RecId)
                        {
                            this.initialiseAdditionalDetailsForExciseInformation(metExciseInformationTable,
                            metExciseRegisterEntry,
                            metInventTransExciseRegisterUpdateView,
                            metInventTransExciseRegisterUpdateView.ReferenceCategory);

                            validInsert = true;
                        }
                    }
                }
                else
                {
                    if (InventJournalTable::find(metInventTransExciseRegisterUpdateView.ReferenceId).Posted == NoYes::Yes)
                    {
                        metExciseInformationTable.InventoryQty  = metInventTransExciseRegisterUpdateView.Qty;

                        validInsert = true;
                    }
                }
            
                if (validInsert)
                {
                    if (metExciseInformationTable.validateWrite())
                    {
                        recordInsertList.add(metExciseInformationTable);
                        validInsert = false;

                        info(strfmt("@MET:ExciseInfoSuccess", metExciseInformationTable.ReferenceNumber, metExciseInformationTable.InventTransType));
                    }
                    else
                    {
                        Error("@MET:ExciseInfoTableValidate");
                    }
                }
            }
            
        }
        //This method will be used to upload migrated records. 
        //If any logic change above then need to update here as well
        this.insertMigratedRecords(_contract);

        recordInsertList.insertDatabase();
        dutyRollVarianceRecordInsertList.insertDatabase();
    }

    /// <summary>
    /// Run process method
    /// </summary>
    /// <param name = "_contract">Contract class reference</param>
    public void runExciseInformationTableUpdateForOrder(METExciseInformationTableUpdateContract _contract, InventTransRefId _refId = '')
    {
        SalesLine salesLine;
        InventTrans inventTrans;
        InventTransOrigin inventTransOrigin;
        boolean validInsert;

        while select salesLine
                where salesLine.SalesId == _refId
                && salesLine.SalesStatus == SalesStatus::Invoiced
            join inventTransOrigin
                where inventTransOrigin.InventTransId == salesLine.InventTransId
                && inventTransOrigin.ReferenceCategory == _contract.parmReferenceId()
            join inventTrans 
                where inventTrans.InventTransOrigin == inventTransOrigin.RecId
            notexists join metExciseInformationTable
                where inventTrans.RecId == metExciseInformationTable.InventTransRefRecId
        {
            validInsert = false;

            if ((_contract.parmTransactionType() == METTransactionType::Positive && inventTrans.Qty > 0) ||
                (_contract.parmTransactionType() == METTransactionType::Negative && inventTrans.Qty < 0))
            {
                metExciseInformationTable.clear();
                metExciseInformationTable.ReferenceNumber       = _refId;
                metExciseInformationTable.InventTransType       = _contract.parmReferenceId();
                metExciseInformationTable.InventTransRefRecId   = inventTrans.RecId;
                metExciseInformationTable.ItemId                = salesLine.ItemId;
                metExciseInformationTable.SiteId                = salesLine.inventDim().InventSiteId;
                metExciseInformationTable.InventTransId         = inventTransOrigin.InventTransId;

                metExciseInformationTable.InventoryQty  = inventTrans.Qty;
                metExciseInformationTable.AvailableQty  = 0.00;

                if (metExciseInformationTable.validateWrite())
                {
                    recordInsertList.add(metExciseInformationTable);
                    validInsert = false;

                    info(strfmt("@MET:ExciseInfoSuccess", metExciseInformationTable.ReferenceNumber, metExciseInformationTable.InventTransType));
                }
                else
                {
                    Error("@MET:ExciseInfoTableValidate");
                }
            }
        }
        
        recordInsertList.insertDatabase();
    }

    /// <summary>
    /// Convert the qty with unit of measure. 
    /// </summary>
    /// <param name = "_itemId">Itemid reference</param>
    /// <param name = "_qty">Qty to be converted</param>
    /// <param name = "_fromUnit">From unit reference</param>
    /// <param name = "_toUnit">To unit reference</param>
    /// <returns>Inventqty reference</returns>
    public InventQty convertQty(ItemId              _itemId,
                                PurchQty            _qty, 
                                UnitOfMeasureSymbol _fromUnit, 
                                UnitOfMeasureSymbol _toUnit)
    {
        InventQty       inventqty;

        inventqty = UnitOfMeasureConverter::convert(_qty,
                            UnitOfMeasure::unitOfMeasureIdBySymbol(_fromUnit),
                            UnitOfMeasure::unitOfMeasureIdBySymbol(_toUnit),
                            NoYes::No,
                            InventTable::itemProduct(_itemId),
                            NoYes::No);

        return inventqty;
    }

						
    /// <summary>
    /// Insert records from data migrated. 
    /// </summary>
    /// <param name = "_contract">METExciseInformationTableUpdateContract</param>
    public void insertMigratedRecords(METExciseInformationTableUpdateContract     _contract)
    {
        METExciseRegisterEntry      metExciseRegisterEntry;
        boolean                     validInsert;


        while select forupdate metExciseRegisterEntry
            where metExciseRegisterEntry.RecordCopied == NoYes::No  &&
                metExciseRegisterEntry.Migrated == NoYes::Yes       &&
                metExciseRegisterEntry.OriginType == _contract.parmReferenceId()
        {
            validInsert = false;

            if ((_contract.parmTransactionType() == METTransactionType::Positive && metExciseRegisterEntry.MigratedQty > 0) ||
                (_contract.parmTransactionType() == METTransactionType::Negative && metExciseRegisterEntry.MigratedQty < 0))
            {
                metExciseInformationTable.clear();
                metExciseInformationTable.ReferenceNumber       = metExciseRegisterEntry.OrderNumber;
                metExciseInformationTable.InventTransType       = metExciseRegisterEntry.OriginType;
                metExciseInformationTable.ItemId                = metExciseRegisterEntry.ItemId;
                metExciseInformationTable.SiteId                = metExciseRegisterEntry.SiteId;

                if (metExciseRegisterEntry.OriginType == InventTransType::Purch)
                {
                    InventTable inventTable = InventTable::find(metExciseRegisterEntry.ItemId);

                    metExciseInformationTable.TransactionQty = metExciseRegisterEntry.MigratedQty;

                    metExciseInformationTable.InventoryQty = this.convertQty(metExciseRegisterEntry.ItemId,
                                                                             metExciseRegisterEntry.MigratedQty,
                                                                            inventTable.purchUnitId(),
                                                                            inventTable.inventUnitId());

                    metExciseInformationTable.AvailableQty  = metExciseRegisterEntry.MigratedQty;
                    metExciseInformationTable.Lodgement     = metExciseRegisterEntry.Lodgement;
                    metExciseInformationTable.PackingSlipId = metExciseRegisterEntry.OriginDocumentNumber;
                    validInsert = true;

                    METExciseDutyParameteres    exciseDutyParameteres = METExciseDutyParameteres::find();

                    dutyRollVariance.clear();
                    dutyRollVariance.Lodgement = metExciseInformationTable.Lodgement;
                    dutyRollVariance.ItemId = metExciseInformationTable.ItemId;
                    dutyRollVariance.Site   = metExciseInformationTable.SiteId;
                    dutyRollVariance.ClaimQty   = metExciseInformationTable.InventoryQty;

                    METExciseSiteDutySetup  exciseSiteDutySetup;

                    select firstonly exciseSiteDutySetup
                        where exciseSiteDutySetup.ItemId == metExciseInformationTable.ItemId
                            && exciseSiteDutySetup.SiteId == metExciseInformationTable.SiteId;

                    METDutyRollValuesTable dutyRollValuesTable;
                    METDutyRollValuesLine dutyRollValuesLine;

                    select firstonly AverageVFD from dutyRollValuesLine
                        exists join dutyRollValuesTable
                        where dutyRollValuesTable.RecId == dutyRollValuesLine.RefRecId
                        && dutyRollValuesLine.Site == metExciseInformationTable.SiteId
                        && dutyRollValuesLine.ItemId == metExciseInformationTable.ItemId
                        && dutyRollValuesTable.Status == METDutyRollStatus::Active;

                    dutyRollVariance.AverageVFD = dutyRollValuesLine.AverageVFD;
                    dutyRollVariance.DutyValue = metExciseRegisterEntry.DutyRateReceived;
                    dutyRollVariance.CurrentDutyValue = exciseSiteDutySetup.ValueForDuty;
                    dutyRollVariance.Variance = dutyRollVariance.DutyValue - dutyRollVariance.AverageVFD;

                    METExciseInformationTable   metExciseInformationTableloc;

                    select firstonly metExciseInformationTableloc
                        group by ReferenceNumber
                        where metExciseInformationTableloc.Itemid == metExciseInformationTable.ItemId;

                    if (!metExciseInformationTableloc)
                    {
                        dutyRollVariance.AverageVFD = 0;
                        dutyRollVariance.Variance = 0;
                    }

                    dutyRollVariance.VarianceAmount = decRound(dutyRollVariance.Variance, 2) * decRound(dutyRollVariance.ClaimQty, 2);

                    if (exciseDutyParameteres.DutyRollVarianceThreshold < dutyRollVariance.Variance)
                    {
                        dutyRollVariance.VarianceExceedsThreshold = NoYes::Yes;
                    }

                    METInventTable metInventTable = METInventTable::find(metExciseInformationTable.ItemId);
                    METTariffItemCode tariffItemCode = METTariffItemCode::findRecId(metInventTable.METTariffItemCodeBaseRecid);
                    dutyRollVariance.AdValoremRate = tariffItemCode.AdValoremOrBeerSubsidyRate;
                    dutyRollVariance.ClaimAmount = (dutyRollVariance.AdValoremRate / 100) * dutyRollVariance.VarianceAmount;
                    dutyRollVariance.InventTransType = metExciseInformationTable.InventTransType;
                    dutyRollVariance.OrderNumber = metExciseInformationTable.ReferenceNumber;
                    dutyRollVariance.VendAccount = (select firstonly OrderAccount from PurchTable where PurchTable.PurchId == dutyRollVariance.OrderNumber).OrderAccount;
                    
                    
                    if (dutyRollVariance.validateWrite())
                    {
                        dutyRollVarianceRecordInsertList.add(dutyRollVariance);
                    }
                }
            
                if (validInsert)
                {
                    if (metExciseInformationTable.validateWrite())
                    {
                        metExciseRegisterEntry.RecordCopied = NoYes::Yes;
                        metExciseRegisterEntry.update();

                        recordInsertList.add(metExciseInformationTable);
                        validInsert = false;

                        info(strfmt("@MET:ExciseInfoSuccess", metExciseInformationTable.ReferenceNumber, metExciseInformationTable.InventTransType));
                    }
                    else
                    {
                        Error("@MET:ExciseInfoTableValidate");
                    }
                }
            }
        }
    }

    private void initialiseAdditionalDetailsForExciseInformation(METExciseInformationTable _metExciseInformationTable,
                                                                 METExciseRegisterEntry metExciseRegisterEntry,
                                                                 METInventTransExciseRegisterUpdateView metInventTransExciseRegisterUpdateView,
                                                                 InventTransType _inventTransType)
    {
        if (metExciseRegisterEntry.RecId)
        {
            switch(_inventTransType)
            {
                case (InventTransType::Purch) :
                case (InventTransType::TransferOrderShip):
                case (InventTransType::TransferOrderReceive):
                    {
                        _metExciseInformationTable.Lodgement     = metExciseRegisterEntry.Lodgement;
                        _metExciseInformationTable.PackingSlipId = metExciseRegisterEntry.OriginDocumentNumber;//metInventTransExciseRegisterUpdateView.PackingSlipId;

                        METExciseDutyParameteres exciseDutyParameteres = METExciseDutyParameteres::find();

                        dutyRollVariance.clear();
                        dutyRollVariance.Lodgement = _metExciseInformationTable.Lodgement;
                        dutyRollVariance.ItemId = _metExciseInformationTable.ItemId;
                        dutyRollVariance.Site   = _metExciseInformationTable.SiteId;
                        dutyRollVariance.ClaimQty   = _metExciseInformationTable.InventoryQty;

                        
                        METExciseSiteDutySetup  exciseSiteDutySetup;

                        select firstonly exciseSiteDutySetup
                            where exciseSiteDutySetup.ItemId == _metExciseInformationTable.ItemId
                                && exciseSiteDutySetup.SiteId == _metExciseInformationTable.SiteId;

                        METDutyRollValuesTable dutyRollValuesTable;
                        METDutyRollValuesLine dutyRollValuesLine;

                        select firstonly AverageVFD from dutyRollValuesLine
                        exists join dutyRollValuesTable
                            where dutyRollValuesTable.RecId == dutyRollValuesLine.RefRecId
                                && dutyRollValuesLine.Site == _metExciseInformationTable.SiteId
                                && dutyRollValuesLine.ItemId == _metExciseInformationTable.ItemId
                                && dutyRollValuesTable.Status == METDutyRollStatus::Active;

                        dutyRollVariance.AverageVFD = dutyRollValuesLine.AverageVFD;
                        dutyRollVariance.DutyValue = metExciseRegisterEntry.DutyRateReceived;
                        dutyRollVariance.CurrentDutyValue = exciseSiteDutySetup.ValueForDuty;
                        dutyRollVariance.Variance = dutyRollVariance.DutyValue - dutyRollVariance.AverageVFD;

                        METExciseInformationTable   metExciseInformationTableloc;

                        select firstonly metExciseInformationTableloc
                            group by ReferenceNumber
                            where metExciseInformationTableloc.Itemid == _metExciseInformationTable.ItemId;

                        if (!metExciseInformationTableloc)
                        {
                            dutyRollVariance.AverageVFD = 0;
                            dutyRollVariance.Variance = 0;
                        }
                        dutyRollVariance.VarianceAmount = decRound(dutyRollVariance.Variance, 2) * decRound(dutyRollVariance.ClaimQty, 2);

                        if (exciseDutyParameteres.DutyRollVarianceThreshold < dutyRollVariance.Variance)
                        {
                            dutyRollVariance.VarianceExceedsThreshold = NoYes::Yes;
                        }

                        METInventTable metInventTable = METInventTable::find(_metExciseInformationTable.ItemId);
                        METTariffItemCode tariffItemCode = METTariffItemCode::findRecId(metInventTable.METTariffItemCodeBaseRecid);
                        dutyRollVariance.AdValoremRate = tariffItemCode.AdValoremOrBeerSubsidyRate;
                        dutyRollVariance.ClaimAmount = dutyRollVariance.AdValoremRate * dutyRollVariance.VarianceAmount;

                        dutyRollVariance.OrderNumber = _metExciseInformationTable.ReferenceNumber;
                        dutyRollVariance.VendAccount = (select firstonly OrderAccount from PurchTable where PurchTable.PurchId == dutyRollVariance.OrderNumber).OrderAccount;
                        dutyRollVariance.InventTransType = _inventTransType;

                        if (dutyRollVariance.validateWrite())
                        {
                            dutyRollVarianceRecordInsertList.add(dutyRollVariance);
                        }

                        break;
                    }
            }
        }
    }
